    [Fact]
    public async Task GeneratedAuthorizationPreservesHtmlAndJsonStringSemantics()
    {
        const string html = "<!doctype html>\n<html><body>Consent &amp; login</body></html>";
        using var http = new HttpClient(new HtmlResponseHandler(html));
        using var client = new SellAppClient(new SellAppOptions { HttpClient = http });
        var service = new OAuthService(client);
        var first = await service.GetAuthorizationRequestWithResponseAsync();
        Assert.Equal(html, first.Value); Assert.Equal(html, first.RawBody);
        Assert.Equal(200, first.Status); Assert.Equal("html-request", first.RequestId);
        Assert.Equal(html, await service.GetAuthorizationRequestAsync());
        var redirect = await service.GetAuthorizationRequestWithResponseAsync();
        Assert.Equal(302, redirect.Status); Assert.Equal("", redirect.Value);
        Assert.Equal("https://example.invalid/callback", redirect.Headers["Location"][0]);
    }
    private sealed class HtmlResponseHandler(string html) : HttpMessageHandler
    {
        private int calls;
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
        {
            calls++;
            var response = new HttpResponseMessage(calls == 3 ? HttpStatusCode.Redirect : HttpStatusCode.OK)
            {
                Content = new StringContent(calls == 3 ? "" : calls == 2 ? JsonConvert.SerializeObject(html) : html, Encoding.UTF8, calls == 2 ? "application/json" : "text/html")
            };
            response.Headers.Add("X-Request-ID", "html-request");
            response.Headers.Location = new Uri("https://example.invalid/callback");
            return Task.FromResult(response);
        }
    }

