    [Fact]
    public async Task IsolatesOperationCredentialsAndEncodesProtocolForms()
    {
        var mock = new HttpMock();
        mock.MockResponseForAnyRequest(HttpStatusCode.NoContent, "");
        using var client = new SellAppClient(new SellAppOptions { ApiKey = "key", CustomerSession = "session", BaseUrl = "https://mock.invalid/api", HttpClient = mock.HttpClient, MaxRetries = 0 });
        await client.MakeRawAPIRequest(new SellAppRequest { Method = HttpMethod.Get, Path = "/v2/orders" });
        mock.AssertHeader("Authorization", "Bearer key");
        Assert.False(mock.CapturedRequests.Last().Headers.ContainsKey("X-STORE"));
        await client.MakeRawAPIRequest(new SellAppRequest { Method = HttpMethod.Get, Path = "/v2/customer-portal/me" });
        mock.AssertHeader("Authorization", "Bearer session");
        await client.MakeRawAPIRequest(new SellAppRequest { Method = HttpMethod.Post, Path = "/oauth/token", Options = new { grant_type = "refresh_token", refresh_token = "secret + value" } });
        Assert.Equal("/oauth/token", mock.CapturedRequests.Last().Uri.AbsolutePath);
        Assert.False(mock.CapturedRequests.Last().Headers.ContainsKey("Authorization"));
        mock.AssertContentTypeStartsWith("application/x-www-form-urlencoded");
        await mock.AssertRequestBodyContainsAsync("refresh_token", "secret + value");
        using var oauth = new SellAppClient(new SellAppOptions { AccessToken = "oauth", Store = "store", HttpClient = mock.HttpClient, MaxRetries = 0 });
        await oauth.MakeRawAPIRequest(new SellAppRequest { Method = HttpMethod.Get, Path = "/v2/orders" });
        mock.AssertHeader("Authorization", "Bearer oauth"); mock.AssertHeader("X-STORE", "store");
        await oauth.MakeRawAPIRequest(new SellAppRequest { Method = HttpMethod.Get, Path = "/v2/me" });
        Assert.False(mock.CapturedRequests.Last().Headers.ContainsKey("X-STORE"));
    }

